-- =====================================================================
-- Estiramientos y abdominales para las rutinas de stretching y zona media.
-- Catálogo global, cada uno con su video de YouTube (revisados con «Revisar videos»).
-- No duplica nombres existentes.
-- =====================================================================
insert into public.exercises (name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues, video_url)
select v.* from (values
('Estiramiento de isquiotibiales','movilidad',array['Isquiotibiales']::text[],array[]::text[],true,'De pie, apoyá el talón de una pierna adelante (en el piso o en un escalón) con la rodilla estirada e inclinate desde la cadera con la espalda larga hasta sentir la parte de atrás del muslo.','Espalda recta, se inclina la cadera. Respirá lento. Sin rebotes.','https://www.youtube.com/watch?v=Lz12BhDfDpA'),
('Estiramiento de cuádriceps de pie','movilidad',array['Cuádriceps','Flexores de cadera']::text[],array[]::text[],true,'De pie, agarrá el empeine y llevá el talón hacia el glúteo, con las rodillas juntas. Apoyate en una pared si hace falta.','Rodillas juntas. Glúteo apretado y cadera hacia adelante. Sin arquear la espalda.','https://www.youtube.com/watch?v=uhP7-OCYQKk'),
('Estiramiento de glúteo (figura 4)','movilidad',array['Glúteos','Piriforme']::text[],array['Colchoneta']::text[],true,'Boca arriba, cruzá el tobillo sobre la rodilla contraria y llevá las dos piernas hacia el pecho agarrando el muslo de abajo.','Cabeza y hombros apoyados. Rodilla de arriba hacia afuera. Respirá y aflojá.','https://www.youtube.com/watch?v=2VE_NLcNMvQ'),
('Estiramiento de pecho en pared','movilidad',array['Pectorales','Hombros']::text[],array[]::text[],true,'Apoyá el antebrazo en una pared o en el marco de una puerta con el codo a la altura del hombro y girá el cuerpo hacia el otro lado hasta sentir el pecho.','Hombro abajo y atrás. Giro suave del torso. Sin forzar el hombro.','https://www.youtube.com/watch?v=vPzPD-KLKJs'),
('Estiramiento de hombro con brazo cruzado','movilidad',array['Hombros','Espalda alta']::text[],array[]::text[],true,'Cruzá un brazo estirado por delante del pecho y acercalo con la otra mano a la altura del codo.','Hombro lejos de la oreja. Brazo a la altura del pecho. Respirá.','https://www.youtube.com/watch?v=dOmT0JCuTZg'),
('Estiramiento de aductores (mariposa)','movilidad',array['Aductores','Cadera']::text[],array['Colchoneta']::text[],false,'Sentado, juntá las plantas de los pies y acercá los talones. Con la espalda larga, dejá caer las rodillas hacia el piso e inclinate un poco hacia adelante.','Espalda recta. Las rodillas bajan solas, sin empujarlas fuerte.','https://www.youtube.com/watch?v=Ob9joyd2fRA'),
('Estiramiento de gemelos en pared','movilidad',array['Gemelos','Sóleo']::text[],array[]::text[],true,'Con las manos en la pared, llevá una pierna atrás con el talón apoyado y la rodilla estirada, y empujá la cadera hacia la pared.','Talón de atrás en el piso. Pie mirando hacia adelante. Después repetí con la rodilla flexionada.','https://www.youtube.com/watch?v=1-uPT7huss0'),
('Postura del niño','movilidad',array['Espalda baja','Dorsales','Cadera']::text[],array['Colchoneta']::text[],false,'De rodillas, sentate sobre los talones y llevá los brazos estirados hacia adelante apoyando el pecho y la frente en el piso.','Glúteos hacia los talones. Brazos largos. Respiración profunda hacia la espalda.','https://www.youtube.com/watch?v=0WoxPLRRbJU'),
('Estiramiento de cobra','movilidad',array['Abdominales','Espalda baja','Flexores de cadera']::text[],array['Colchoneta']::text[],false,'Boca abajo, con las manos debajo de los hombros, estirá los brazos de a poco levantando el pecho y dejando la cadera apoyada.','Cadera en el piso. Hombros lejos de las orejas. Subí solo hasta donde no moleste la espalda.','https://www.youtube.com/watch?v=tR-3cDLj1jE'),
('Abdominales cortos (crunch)','core',array['Abdominales']::text[],array['Colchoneta']::text[],false,'Boca arriba con las rodillas flexionadas, levantá los hombros del piso llevando las costillas hacia la cadera y bajá controlado.','Mirada al techo. Sin tirar del cuello. Exhalá al subir.','https://www.youtube.com/watch?v=hl9Yu7UZqHU')
) as v(name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues, video_url)
where not exists (select 1 from public.exercises e where e.org_id is null and e.name = v.name);
